from pathlib import Path
import base64,json,html
app=Path(__file__).resolve().parents[1];cfg=json.loads((app/'.docs/phone-screen-catalog.json').read_text());groups=list(dict.fromkeys(c['group'] for c in cfg))
parts=['''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GROMO · 전체 앱 화면</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#F1F1EF;color:#493B39;font-family:-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo",sans-serif}header{max-width:1570px;margin:auto;padding:58px 38px 32px}header .eyebrow{font-size:12px;letter-spacing:2px;font-weight:800;color:#99746D}h1{font-size:42px;letter-spacing:-1.8px;margin:13px 0 12px}header p{font-size:15px;line-height:1.8;margin:0;color:#756965}.pink{color:#DB6C8D}nav{display:flex;flex-wrap:wrap;gap:8px;margin-top:25px}nav a{font-size:12px;text-decoration:none;color:#665651;background:#FFFFFF;border:1px solid #DED8D4;padding:10px 13px;border-radius:30px}nav a:hover{background:#FFE2EA}.meta{display:flex;gap:16px;flex-wrap:wrap;margin-top:22px;font-size:12px;color:#786A62}main{max-width:1570px;margin:auto;padding:0 38px 80px}.group{margin-top:38px;scroll-margin-top:20px}.sectionhead{display:flex;align-items:baseline;gap:16px;margin:0 0 30px;padding:22px 0;border-top:1px solid #DAD6D1}h2{font-size:23px;letter-spacing:-.8px;margin:0}.sectionhead span{color:#96857C;font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:38px 30px}.tile{min-width:0}.device{border:2px solid #71534B;border-radius:45px;padding:8px;background:#FFFDF8;box-shadow:0 7px 0 #DCD4CB,0 18px 38px #4C3C2B0B;overflow:hidden;cursor:zoom-in;width:100%;max-width:336px;margin:auto}.screen{position:relative;aspect-ratio:402/874;overflow:hidden;border-radius:35px;background:#FFF7EB}.status{height:5.95%;position:absolute;top:0;left:0;right:0;z-index:2;pointer-events:none;display:flex;align-items:center;justify-content:space-between;padding:0 7%;font-size:12px;font-weight:750;color:#493B39}.island{position:absolute;top:11%;left:36%;width:28%;height:49%;border-radius:20px;background:#493B39}.status .icons{font-size:10px;letter-spacing:1px}.shot{display:block;width:100%;height:100%;object-fit:contain}.homebar{height:3.66%;position:absolute;bottom:0;left:0;right:0;pointer-events:none}.homebar:after{content:"";position:absolute;width:31%;height:4px;border-radius:8px;background:#493B39;bottom:24%;left:34.5%}.caption{max-width:336px;margin:18px auto 0;display:flex;align-items:baseline;gap:10px;line-height:1.5}.num{font-size:10px;color:#A98473;border:1px solid #D6C3B6;padding:2px 5px;border-radius:6px}.caption strong{font-size:14px;font-weight:750}.caption small{display:block;color:#8D7D75;font-size:10px;font-weight:500;margin-top:3px}.end{padding-top:55px;font-size:12px;color:#93847A}dialog{border:0;background:transparent;padding:0;max-height:98vh;max-width:95vw;overflow:visible}dialog::backdrop{background:#352F2BE8}dialog .device{width:min(420px,90vw);max-height:94vh;max-width:43.1vh;cursor:zoom-out;box-shadow:none}dialog .caption{display:none}dialog .status{font-size:13px}.close{position:fixed;right:25px;top:20px;color:white;background:#ffffff20;border:1px solid #ffffff55;border-radius:30px;width:44px;height:44px;cursor:pointer;font-size:22px}@media(min-width:1650px){.grid{gap:50px 40px}}@media(max-width:1180px){.grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:32px 25px}}@media(max-width:820px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:30px 20px}main,header{padding-left:20px;padding-right:20px}h1{font-size:33px}.device{border-radius:35px}.screen{border-radius:27px}}@media(max-width:500px){.grid{grid-template-columns:1fr}.device{max-width:340px}.caption{max-width:340px}header{padding-top:35px}}
</style><header><div class="eyebrow">GROMO · STRAWBERRY SODA</div><h1>우리의 하루가 자라는 <span class="pink">작은 섬.</span></h1><p>첫 만남부터 집중, 마을의 성장, 나만의 취향까지.<br>같은 크기의 폰 안에 전체 앱 화면을 펼쳐두었어요.</p><div class="meta"><span>'''+str(len(cfg))+'''개 화면·상태</span><span>React Native 앱의 실제 렌더링</span><span>화면을 누르면 크게 보기</span></div><nav>''']
for i,g in enumerate(groups):parts.append(f'<a href="#group{i}">{html.escape(g)}</a>')
parts.append('</nav></header><main>')
for i,g in enumerate(groups):
 items=[c for c in cfg if c['group']==g];parts.append(f'<section class="group" id="group{i}"><div class="sectionhead"><h2>{html.escape(g)}</h2><span>{len(items)} screens</span></div><div class="grid">')
 for c in items:
  src=base64.b64encode((app/'.docs/phone-screens'/f"{c['id']}.png").read_bytes()).decode();bg='#f0f2df' if c['route'] in ['arrival','travel'] else '#ADE1F8' if c['route'] in ['home','focus','rest','arrival','travel'] else '#FFF7EB'
  parts.append(f'''<article class="tile"><div class="device" role="button" tabindex="0" aria-label="{html.escape(c['title'])} 크게 보기"><div class="screen" style="background:{bg}"><div class="status"><span>9:41</span><span class="island"></span><span class="icons">▮▮▮ ▰</span></div><img class="shot" loading="lazy" src="data:image/png;base64,{src}" alt="{html.escape(c['title'])}"><div class="homebar"></div></div></div><div class="caption"><span class="num">{c['id']}</span><strong>{html.escape(c['title'])}{'<small>같은 화면의 아래쪽 내용</small>' if c.get('bottom') else ''}</strong></div></article>''')
 parts.append('</div></section>')
parts.append('''<p class="end">앱 화면의 크림 배경과 화면 모음의 중성 배경을 구분했습니다. 로그인·그룹 상태·재화·기록·구매는 로컬 목업으로 동작합니다.</p></main><dialog id="zoom"><button class="close" aria-label="닫기">×</button><div id="zoomcontent"></div></dialog><script>const d=document.querySelector('dialog');function show(el){document.querySelector('#zoomcontent').replaceChildren(el.cloneNode(true));d.showModal()}document.querySelectorAll('.tile .device').forEach(el=>{el.addEventListener('click',()=>show(el));el.addEventListener('keydown',e=>{if(e.key==='Enter')show(el)})});d.addEventListener('click',()=>d.close())</script></html>''')
out=app/'.docs/RN-전체화면-캡처.html';out.write_text(''.join(parts));print(out, out.stat().st_size)
